-- Trivia / Quiz Bot question bank (bundled, no remote dependency).
CREATE TABLE IF NOT EXISTS trivia_questions (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  category VARCHAR(32) NOT NULL,
  question VARCHAR(400) NOT NULL,
  opt_a VARCHAR(200) NOT NULL,
  opt_b VARCHAR(200) NOT NULL,
  opt_c VARCHAR(200) NOT NULL,
  opt_d VARCHAR(200) NOT NULL,
  answer TINYINT NOT NULL,
  note VARCHAR(300) NOT NULL DEFAULT '',
  KEY category (category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM trivia_questions;

ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), module=VALUES(module),
  score_label=VALUES(score_label), score_order=VALUES(score_order), enabled=VALUES(enabled), sort=VALUES(sort);
